		if strings.EqualFold(key, name) {
			return name
		}
	}
	return key
}

// canonicalEntryFieldPath 把条目数值字段名归一为 index/term 的标准拼写。
func canonicalEntryFieldPath(key string) string {
	switch {
	case strings.EqualFold(key, "index"):
		return "index"
	case strings.EqualFold(key, "term"):
		return "term"
	default:
		return key
	}
}

